function keyboard(e){let typing=['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName);if(e.key==='Escape'){closeModal();$('menu').hidden=true;penPoints=[];tool='select';return}if(typing)return;let ctrl=e.ctrlKey||e.metaKey;if(ctrl){let key=e.key.toLowerCase();if(['s','z','y','d','c','v','o','a'].includes(key))e.preventDefault();if(key==='s')saveProject();else if(key==='o')$('fileInput').click();else if(key==='z')e.shiftKey?redo():undo();else if(key==='y')redo();else if(key==='d')duplicate();else if(key==='c'&&e.shiftKey)precompose();else if(key==='c'){clipboard=selectedKeys.length?{type:'keys',data:selectedKeys.map(s=>({...s,key:{...comp().layers.find(x=>x.id===s.id).keys[s.p][s.i]}}))}:{type:'layers',data:comp().layers.filter(l=>selected.includes(l.id)).map(l=>JSON.parse(JSON.stringify(l)))};toast('已复制')}else if(key==='v'&&clipboard){action(()=>{if(clipboard.type==='keys'){let min=Math.min(...clipboard.data.map(x=>x.key.t));for(let k of clipboard.data){let l=layer()||comp().layers.find(x=>x.id===k.id);if(!l)continue;l.keys[k.p]??=[];l.keys[k.p].push({...k.key,t:time+k.key.t-min});l.keys[k.p].sort((a,b)=>a.t-b.t)}}else{selected=[];for(let raw of clipboard.data){let l=JSON.parse(JSON.stringify(raw));l.id=F.uid();l.name+=' 副本';comp().layers.unshift(l);selected.push(l.id)}}})}else if(key==='a'){selected=comp().layers.map(x=>x.id);refresh()}return}
if(e.code==='Space'){e.preventDefault();togglePlay()}else if(e.key==='ArrowLeft'){e.preventDefault();setTime(time-(e.shiftKey?10:1)/comp().fps)}else if(e.key==='ArrowRight'){e.preventDefault();setTime(time+(e.shiftKey?10:1)/comp().fps)}else if(e.key==='Home')setTime(0);else if(e.key==='End')setTime(comp().duration);else if(e.key==='F9'){e.preventDefault();interpolate('bezier')}else if(e.key==='Delete'||e.key==='Backspace')deleteSelected();else if(e.key==='Enter'){if(tool==='pen')finishPen();else if(layer()?.type==='precomp'){project.active=layer().compId;selected=[];renderer.reset();refresh()}else rename(layer())}else if(e.key==='j'||e.key==='k'){let ts=comp().layers.filter(l=>selected.includes(l.id)).flatMap(l=>Object.values(l.keys).flat().map(k=>k.t)).sort((a,b)=>a-b);setTime(e.key==='j'?[...ts].reverse().find(t=>t<time-.01)??0:ts.find(t=>t>time+.01)??comp().duration)}else if(['v','w','y','g','q','t'].includes(e.key.toLowerCase())){let map={v:'select',w:'rotate',y:'anchor',g:'pen',q:'rect',t:'text'};tool=map[e.key.toLowerCase()];$$('[data-tool]').forEach(b=>b.classList.toggle('active',b.dataset.tool===tool))}}
